llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Pethidine, a 4-phenylpiperidine opioid with a basic amine, has absolute oral bioavailability of 0.52 (0.47–0.61) in healthy subjects, directly supporting F ≥ 20% for the query's similar piperidine-based scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide, an anilide piperidine with methoxy substitution, shows absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20% for the query's anilidopiperidine with methoxymethyl and basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Ziprasidone, a thiophene-containing basic amine drug, has about 60% absolute oral bioavailability in the fed state, supporting high oral bioavailability for the query's thiophene-containing piperidine amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Meptazinol has low absolute oral bioavailability (4.5–8.7%), but this is driven by extensive first-pass glucuronidation of its phenolic group and an azepane core, features absent in the query; this contradictory evidence is outweighed by structurally closer high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer human absolute oral bioavailability data from structurally related piperidine/amide and anilidopiperidine drugs (pethidine ~52%, encainide ~32%, ziprasidone ~60%) supports F ≥ 20%. The only low-F analogue, meptazinol, owes its low bioavailability to phenolic glucuronidation not present in the query, so it does not overturn the supportive evidence.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself; prediction relies on close analogues.",
    "The query's first-pass metabolic stability is not directly measured; 4-anilidopiperidines can vary in hepatic extraction.",
    "Food effects on absorption are unknown for the query, though ziprasidone data suggest food can be important."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

